#!/usr/bin/env python3
"""List each line citation in the dumped entries whose file BASE..AT changed, with its
old and new line and whether the cited text is the same at both. Read-only."""
import re, subprocess, os, sys, collections
WT = '/home/user/fortress-landing-32'
S = os.path.dirname(os.path.abspath(__file__))
BASE, AT = 'db352c177', 'c0c35b4f9'

def git(*a):
    return subprocess.run(['git', '-C', WT] + list(a), capture_output=True, text=True).stdout

changed = [f for f in git('diff', '--name-only', BASE, AT).splitlines()
           if not f.startswith(('explorations/', '.claude/', 'docs/'))]
by_base = collections.defaultdict(list)
for f in changed:
    by_base[os.path.basename(f)].append(f)

maps = {}
def linemap(f):
    """old line -> new line, or None where the old line was changed or deleted."""
    if f in maps:
        return maps[f]
    hunks = []
    for l in git('diff', '-U0', BASE, AT, '--', f).splitlines():
        m = re.match(r'@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@', l)
        if m:
            o, on, n, nn = int(m[1]), int(m[2] or 1), int(m[3]), int(m[4] or 1)
            hunks.append((o, on, n, nn))
    def f_(old):
        shift = 0
        for o, on, n, nn in hunks:
            if on == 0:               # pure insertion after old line o
                if old > o:
                    shift += nn
            else:
                if old < o:
                    break
                if old < o + on:
                    return None
                shift += nn - on
        return old + shift
    maps[f] = f_
    return f_

def text(rev, f, n):
    ls = git('show', '%s:%s' % (rev, f)).splitlines()
    return ls[n - 1].strip() if 0 < n <= len(ls) else '<none>'

CITE = re.compile(r'`([^`\s]*?)(?::(\d+)(?:-(\d+))?)`')
out = []
for raw in ('F1.raw', 'F2.raw', 'P.raw'):
    for line in open(os.path.join(S, raw)):
        m = re.match(r'- ([FP]-\d+) ', line)
        if not m:
            continue
        key = m[1]
        cur = None
        for c in CITE.finditer(line):
            path, a, b = c[1], int(c[2]), int(c[3]) if c[3] else None
            if path:
                cur = path
            if not cur:
                continue
            cands = [f for f in by_base.get(os.path.basename(cur), []) if f.endswith(cur)]
            if not cands:
                continue
            if len(cands) > 1:
                out.append('%s  AMBIGUOUS %s %s' % (key, c[0], cands)); continue
            f = cands[0]
            lm = linemap(f)
            for old in ([a] if b is None else [a, b]):
                new = lm(old)
                if new is None:
                    out.append('%s  %s  %s:%d  CHANGED-LINE  base: %s' % (key, c[0], f, old, text(BASE, f, old)[:90]))
                elif new != old:
                    same = text(BASE, f, old) == text(AT, f, new)
                    out.append('%s  %s  %s:%d -> %d  %s  | %s' % (key, c[0], f, old, new, 'same' if same else 'DIFF', text(AT, f, new)[:80]))
print('\n'.join(out))
print(len(out), 'line ends;', len({o.split()[0] for o in out}), 'entries')

